import { createForks, createWorkspace, teardownForks, teardownWorkspace } from '@tigrisdata/agent-kit';
import { GetObjectCommand, ListObjectsV2Command, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { writeFile } from 'fs/promises';
import { Readable } from 'stream';

const ENDPOINT = 'REDACTED';
const REGION = 'REDACTED';
const BASE_BUCKET = 'gold-eval-dataset';
const FORK_PREFIX = 'eval-attempt';
const PROMPTS_PREFIX = 'prompts/';
const ANSWERS_PREFIX = 'answers/';

type AccessCredentials = {
  accessKeyId: string;
  secretAccessKey: string;
};

type ForkInfo = {
  bucket: string;
  credentials?: AccessCredentials;
};

type ForkSet = {
  forks: ForkInfo[];
};

type WorkspaceInfo = {
  bucket: string;
  credentials?: AccessCredentials;
};

const createS3Client = (credentials: AccessCredentials): S3Client =>
  new S3Client({
    region: REGION,
    endpoint: ENDPOINT,
    credentials,
    forcePathStyle: true,
  });

const streamToString = async (body: unknown): Promise<string> => {
  if (typeof body === 'string') {
    return body;
  }

  if (body instanceof Uint8Array) {
    return Buffer.from(body).toString('utf-8');
  }

  if (body && typeof (body as { transformToString?: () => Promise<string> }).transformToString === 'function') {
    return (body as { transformToString: () => Promise<string> }).transformToString();
  }

  if (body instanceof Readable) {
    const chunks: Buffer[] = [];
    for await (const chunk of body) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }
    return Buffer.concat(chunks).toString('utf-8');
  }

  throw new Error('Unsupported response body type');
};

const listKeys = async (s3: S3Client, bucket: string, prefix: string): Promise<string[]> => {
  const keys: string[] = [];
  let continuationToken: string | undefined;

  do {
    const response = await s3.send(
      new ListObjectsV2Command({
        Bucket: bucket,
        Prefix: prefix,
        ContinuationToken: continuationToken,
      }),
    );

    for (const item of response.Contents ?? []) {
      if (item.Key) {
        keys.push(item.Key);
      }
    }

    continuationToken = response.IsTruncated ? response.NextContinuationToken : undefined;
  } while (continuationToken);

  return keys;
};

const readObjectText = async (s3: S3Client, bucket: string, key: string): Promise<string> => {
  const response = await s3.send(
    new GetObjectCommand({
      Bucket: bucket,
      Key: key,
    }),
  );

  if (!response.Body) {
    throw new Error(`Missing body for ${bucket}/${key}`);
  }

  return streamToString(response.Body);
};

const writeObjectText = async (s3: S3Client, bucket: string, key: string, value: string): Promise<void> => {
  await s3.send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: Buffer.from(value, 'utf-8'),
      ContentType: 'text/plain; charset=utf-8',
    }),
  );
};

const reverseText = (text: string): string => text.split('').reverse().join('');

const processFork = async (
  fork: ForkInfo,
  index: number,
  workspaceName: string,
): Promise<{ workspace: WorkspaceInfo; answers: Record<string, string> }> => {
  if (!fork.credentials) {
    throw new Error(`Missing credentials for fork ${fork.bucket}`);
  }

  const { data: workspace, error: workspaceError } = await createWorkspace(workspaceName, {
    credentials: { role: 'Editor' },
  });

  if (workspaceError || !workspace) {
    throw workspaceError ?? new Error(`Failed to create workspace ${workspaceName}`);
  }

  if (!workspace.credentials) {
    throw new Error(`Missing credentials for workspace ${workspaceName}`);
  }

  const forkS3 = createS3Client(fork.credentials);
  const writerS3 = createS3Client(workspace.credentials);
  const promptKeys = await listKeys(forkS3, fork.bucket, PROMPTS_PREFIX);
  const answers: Record<string, string> = {};

  await Promise.all(
    promptKeys.map(async (key) => {
      const promptText = await readObjectText(forkS3, fork.bucket, key);
      const reversed = reverseText(promptText);
      const promptId = key.split('/').pop()?.replace('.json', '') ?? `p${index}`;
      const answerKey = `${ANSWERS_PREFIX}${promptId}.txt`;

      await writeObjectText(writerS3, workspace.bucket, answerKey, reversed);
      answers[promptId] = reversed;
    }),
  );

  return { workspace, answers };
};

const main = async (): Promise<void> => {
  let forkSet: ForkSet | null = null;
  const workspaces: WorkspaceInfo[] = [];

  try {
    const { data: createdForks, error: forkError } = await createForks(BASE_BUCKET, 3, {
      prefix: FORK_PREFIX,
      credentials: { role: 'ReadOnly' },
    });

    if (forkError || !createdForks) {
      throw forkError ?? new Error('Failed to create forks');
    }

    forkSet = createdForks as ForkSet;

    const results = await Promise.all(
      forkSet.forks.map((fork, index) =>
        processFork(fork, index, `eval-writer-${index}`),
      ),
    );

    for (const result of results) {
      workspaces.push(result.workspace);
    }

    const aggregated: Record<string, Record<string, string>> = {};

    await Promise.all(
      forkSet.forks.map(async (fork, index) => {
        const workspace = results[index].workspace;

        if (!workspace.credentials) {
          throw new Error(`Missing credentials for workspace ${workspace.bucket}`);
        }

        const writerS3 = createS3Client(workspace.credentials);
        const answerKeys = await listKeys(writerS3, workspace.bucket, ANSWERS_PREFIX);
        const bucketAnswers: Record<string, string> = {};

        await Promise.all(
          answerKeys.map(async (key) => {
            const answerText = await readObjectText(writerS3, workspace.bucket, key);
            const answerId = key.split('/').pop()?.replace('.txt', '') ?? key;
            bucketAnswers[answerId] = answerText;
          }),
        );

        aggregated[fork.bucket] = bucketAnswers;
      }),
    );

    await writeFile('/home/user/orchestrator/aggregated.json', JSON.stringify(aggregated, null, 2));
  } finally {
    await Promise.allSettled(workspaces.map((workspace) => teardownWorkspace(workspace)));

    if (forkSet) {
      await teardownForks(forkSet);
    }
  }
};

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

